import math

def max_Prime_Factors(n):
    maxPrime = -1
    # Handle the smallest prime number
    if n % 2 == 0:
        maxPrime = 2
        while n % 2 == 0:
            n //= 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            maxPrime = i
            n //= i
